# Build and decode I/O control codes for a made-up driver, ToyFan.
METHOD = {0: "BUFFERED", 1: "IN_DIRECT", 2: "OUT_DIRECT", 3: "NEITHER"}
ACCESS = {0: "ANY_ACCESS", 1: "READ_DATA", 2: "WRITE_DATA", 3: "READ|WRITE"}

def ctl_code(device_type, function, method, access):
    return (device_type << 16) | (access << 14) | (function << 2) | method

def decode(code):
    return {"device": hex(code >> 16), "access": ACCESS[(code >> 14) & 3],
            "function": hex((code >> 2) & 0xFFF), "method": METHOD[code & 3]}

TOYFAN = 0x8001                                  # vendor range is 0x8000-0xFFFF
GET_SPEED = ctl_code(TOYFAN, 0x800, 0, 1)        # read the fan speed
SET_SPEED = ctl_code(TOYFAN, 0x801, 0, 2)        # change the fan speed
for name, code in [("GET_SPEED", GET_SPEED), ("SET_SPEED", SET_SPEED)]:
    print(name, hex(code), decode(code))

# Output:
# GET_SPEED 0x80016000 {'device': '0x8001', 'access': 'READ_DATA', 'function': '0x800', 'method': 'BUFFERED'}
# SET_SPEED 0x8001a004 {'device': '0x8001', 'access': 'WRITE_DATA', 'function': '0x801', 'method': 'BUFFERED'}

# Toy model of kernel driver signing rules (simplified from Microsoft's
# Driver Signing Policy page; real code integrity checks much more).
from datetime import date
CUTOFF = date(2015, 7, 29)

def may_load(drv, host):
    if drv["sig"] == "none":
        return False, "unsigned"
    if drv["sig"] in ("whcp", "attestation"):
        return True, "signed by Microsoft (Dev Center)"
    if host["trust_removed"] and not drv.get("allowlisted"):
        return False, "2026 policy: cross-signed, not allow-listed"
    if not host["secure_boot"] or drv["leaf"] < CUTOFF:
        return True, "cross-signed exception applies"
    return False, "cross-signed, leaf after cutoff, Secure Boot on"

drivers = [("newfan.sys",  {"sig": "whcp"}),
           ("labtool.sys", {"sig": "attestation"}),
           ("oldutil.sys", {"sig": "cross", "leaf": date(2013, 5, 2)}),
           ("late.sys",    {"sig": "cross", "leaf": date(2016, 1, 9)})]
hosts = {"win10, Secure Boot on":  {"secure_boot": True,  "trust_removed": False},
         "win10, Secure Boot off": {"secure_boot": False, "trust_removed": False},
         "win11 24H2, enforced":   {"secure_boot": True,  "trust_removed": True}}
for hname, h in hosts.items():
    print("==", hname)
    for name, d in drivers:
        ok, why = may_load(d, h)
        print(f"  {name:12} {'LOAD ' if ok else 'BLOCK'} {why}")

