// ToyFan v1: made-up driver, pseudocode. THE VULNERABLE VERSION.
// DriverEntry gave \Device\ToyFan an SDDL that lets Everyone open it,
// and declared the IOCTL like this:
//   IOCTL_TOYFAN_SET_REG = CTL_CODE(0x8001, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct { ULONG Reg; ULONG64 Value; } TOYFAN_REQ;

NTSTATUS ToyFanDeviceControl(PDEVICE_OBJECT dev, PIRP irp)
{
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    TOYFAN_REQ *req = irp->AssociatedIrp.SystemBuffer;
    NTSTATUS status;

    switch (sp->Parameters.DeviceIoControl.IoControlCode) {
    case IOCTL_TOYFAN_SET_REG:
        // no input length check, no limit on Reg or Value
        __writemsr(req->Reg, req->Value);
        status = STATUS_SUCCESS;
        break;
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
    }
    irp->IoStatus.Status = status;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

