        break;
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
    }
    irp->IoStatus.Status = status;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

// ToyFan v2: made-up driver, pseudocode. THE FIXED VERSION.
// 1. Only SYSTEM and Administrators may open the device, and the ACL also
//    covers names below \Device\ToyFan (FILE_DEVICE_SECURE_OPEN).
DECLARE_CONST_UNICODE_STRING(sddl, L"D:P(A;;GA;;;SY)(A;;GA;;;BA)");
status = IoCreateDeviceSecure(drv, 0, &name, 0x8001, FILE_DEVICE_SECURE_OPEN,
                              FALSE, &sddl, &TOYFAN_CLASS_GUID, &dev);

// 2. The interface offers one narrow operation, and asks for write access.
#define IOCTL_TOYFAN_SET_SPEED CTL_CODE(0x8001, 0x801, METHOD_BUFFERED, FILE_WRITE_DATA)
typedef struct { ULONG Rpm; } TOYFAN_SPEED;

case IOCTL_TOYFAN_SET_SPEED:
    // 3. Check the buffer is big enough before reading it.
    if (sp->Parameters.DeviceIoControl.InputBufferLength < sizeof(TOYFAN_SPEED)) {
        status = STATUS_BUFFER_TOO_SMALL; break;
    }
    TOYFAN_SPEED *s = irp->AssociatedIrp.SystemBuffer;
    // 4. Constrain the value; the register is fixed by the driver, not the caller.
    if (s->Rpm > TOYFAN_MAX_RPM) { status = STATUS_INVALID_PARAMETER; break; }
    __writemsr(TOYFAN_FAN_MSR, s->Rpm);
    status = STATUS_SUCCESS;
    break;

blocks.md:
Microsoft's rules for IOCTL buffers, from *Security Issues for I/O Control Codes* and the checklist:
- check `InputBufferLength` and `OutputBufferLength` before touching the system buffer;
- zero driver-allocated output buffers, and report the real output length, or kernel memory leaks back to the caller (the checklist's example: returning 4K when only 200 bytes were written);
- prefer `METHOD_BUFFERED`; avoid `METHOD_NEITHER`, and when you must use it, call `ProbeForRead` or `ProbeForWrite` and wrap every access in an exception handler;
- "copy any parameters that need to be validated from the user data buffer to memory that is solely accessible from kernel mode ... Then ... validate and then operate on the data".

