// Pseudocode: a METHOD_NEITHER handler that reads user memory twice.
typedef struct { ULONG Len; CHAR Data[4096]; } TOY_MSG;

NTSTATUS ToyLogWrite(TOY_MSG *user)      // raw user-mode pointer
{
    CHAR buf[64];
    __try {
        ProbeForRead(user, sizeof(TOY_MSG), 1);
        if (user->Len > sizeof(buf))       // fetch 1: check
            return STATUS_INVALID_PARAMETER;
        RtlCopyMemory(buf, user->Data, user->Len);   // fetch 2: use
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return GetExceptionCode();
    }
    return STATUS_SUCCESS;
}

