# Toy App Control driver policy: deny rules first, then allow rules,
# anything else is blocked. Audit mode logs 3076, enforce mode logs 3077.
POLICY = {
    "options": {"Required:WHQL"},
    "deny":  [lambda d: d["orig"] == "toyfan.sys" and d["ver"] <= (1, 4, 0, 65535)],
    "allow": [lambda d: d["whql"] and d["signer"] in {"Contoso HW", "Fabrikam Code Signing"}],
}

def evaluate(d, audit):
    if "Required:WHQL" in POLICY["options"] and not d["whql"]:
        hit = "not WHQL signed"
    elif any(rule(d) for rule in POLICY["deny"]):
        hit = "explicit deny"
    elif any(rule(d) for rule in POLICY["allow"]):
        return "load", None
    else:
        hit = "no allow rule"
    if audit:
        return "load", f"3076 audit: would block ({hit})"
    return "BLOCK", f"3077 enforced ({hit})"

drivers = [
    {"orig": "netx.sys",   "ver": (3, 1, 0, 0), "signer": "Contoso HW", "whql": True},
    {"orig": "toyfan.sys", "ver": (1, 3, 2, 7), "signer": "Fabrikam Code Signing", "whql": True},
    {"orig": "toyfan.sys", "ver": (1, 5, 0, 0), "signer": "Fabrikam Code Signing", "whql": True},
    {"orig": "oldtool.sys", "ver": (2, 0, 0, 0), "signer": "Tailspin", "whql": False},
]
for audit in (True, False):
    print("== audit mode" if audit else "== enforced")
    for d in drivers:
        action, event = evaluate(d, audit)
        print(f'  {d["orig"]:11} {action:5} {event or ""}')
